INSERT INTO public.exam_references (id, exam_id, species, gender, min_age_days, max_age_days, reference_text_content, min_value, max_value, unit) VALUES
    ('2ba5c03d-067a-48ec-8bdd-dce5a61d6195', '164ce5e5-430d-4634-beb8-51864afe20a4', 'Canino', 'Ambos', 0, 180, 'Canino Filhote (0 a 6 meses): Eritrócitos: 4,5 - 6,5 milhões/µL | Hemoglobina: 10,0 - 15,0 g/dL | Hematócrito: 30 - 45% | Leucócitos: 7.000 - 18.500 /µL | Plaquetas: 200.000 - 500.000 /µL', 4.50, 6.50, 'milhões/µL'),
    ('96e6b1f3-4349-483a-9532-cb9ead6046a2', '164ce5e5-430d-4634-beb8-51864afe20a4', 'Canino', 'Ambos', 181, 36500, 'Canino Adulto (> 6 meses): Eritrócitos: 5,5 - 8,5 milhões/µL | Hemoglobina: 12,0 - 18,0 g/dL | Hematócrito: 37 - 55% | Leucócitos: 6.000 - 17.000 /µL | Plaquetas: 200.000 - 500.000 /µL | PPT: 6,0 - 7,5 g/dL', 5.50, 8.50, 'milhões/µL'),
    ('de1fb432-f0ef-4e55-bded-cae1a39ab3b4', '164ce5e5-430d-4634-beb8-51864afe20a4', 'Felino', 'Ambos', 0, 36500, 'Felino: Eritrócitos: 5,0 - 10,0 milhões/µL | Hemoglobina: 8,0 - 15,0 g/dL | Hematócrito: 24 - 45% | Leucócitos: 5.500 - 19.500 /µL | Plaquetas: 300.000 - 800.000 /µL | PPT: 6,0 - 8,0 g/dL', 5.00, 10.00, 'milhões/µL'),
    ('f3370648-9a86-441f-b842-b5614bd1f86e', 'e0052575-fe38-4640-aeea-ff384c0169a8', 'Canino', 'Ambos', 0, 36500, 'Canino Check Up / Bioquímico: Ureia: 21 - 60 mg/dL | Creatinina: 0,5 - 1,5 mg/dL | ALT (TGP): 10 - 88 U/L | Fosfatase Alcalina: 20 - 156 U/L | Albumina: 2,6 - 3,3 g/dL', 0.50, 1.50, 'mg/dL'),
    ('2960cb59-00d7-4d5f-b44b-c27b6c4a8e5b', 'e0052575-fe38-4640-aeea-ff384c0169a8', 'Felino', 'Ambos', 0, 36500, 'Felino Check Up / Bioquímico: Ureia: 30 - 65 mg/dL | Creatinina: 0,8 - 1,8 mg/dL | ALT (TGP): 20 - 100 U/L | Fosfatase Alcalina: 10 - 90 U/L | Albumina: 2,4 - 3,8 g/dL', 0.80, 1.80, 'mg/dL'),
    ('ae90d100-f93d-4a1f-8201-ee48def9ff60', '527152a3-e4ca-4393-8af4-bbf52a3cdf9f', 'Felino', 'Ambos', 0, 36500, 'Coproparasitológico Felino/Canino: Ausência de oocistos de protozoários e ovos de helmintos (0 OPG) em amostra fecal fresca.', 0.00, 0.00, 'ovos/g'),
    ('30e3ca7d-a557-486c-9f10-a1badc72eae7', '35ba6394-e200-4615-9aa0-74711a81620d', 'Canino', 'Ambos', 0, 36500, 'Urocultura por Cistocentese: Amostra fisiologicamente estéril (Ausência de crescimento bacteriano). Contagens >= 1.000 UFC/mL em cistocentese são clinicamente significativas.', 0.00, 1000.00, 'UFC/mL'),
    ('b2512411-b0e9-48e1-8f5d-39b6521b3fe4', 'bd1e7265-384e-40f4-ad05-da0574ca924f', 'Canino', 'Ambos', 180, 36500, 'Canino Adulto Tireoide: T4 Livre: 0,8 - 3,5 ng/dL | TSH Canino: 0,05 - 0,50 ng/mL', 0.80, 3.50, 'ng/dL');
